import{o as n,c as r,j as s,a as t,k as i,g as e,aj as d}from"./chunks/framework.Cn87zHeG.js";const l={tabindex:"0"},o=["href"],h=["href"],u=JSON.parse('{"title":"任务编排控制台","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"faq/console.md","filePath":"faq/console.md"}'),p={name:"faq/console.md"},F=Object.assign(p,{setup(k){return(c,a)=>(n(),r("div",null,[a[5]||(a[5]=s("h1",{id:"任务编排控制台",tabindex:"-1"},[t("任务编排控制台 "),s("a",{class:"header-anchor",href:"#任务编排控制台","aria-label":'Permalink to "任务编排控制台"'},"​")],-1)),a[6]||(a[6]=s("h2",{id:"下载文件",tabindex:"-1"},[t("下载文件 "),s("a",{class:"header-anchor",href:"#下载文件","aria-label":'Permalink to "下载文件"'},"​")],-1)),s("table",l,[a[4]||(a[4]=s("thead",null,[s("tr",null,[s("th",null,"文件"),s("th",null,"大小"),s("th",null,"用途")])],-1)),s("tbody",null,[s("tr",null,[s("td",null,[s("a",{href:i(e)("/downloads/faq/h1-web.tar"),download:""},"下载 h1-web.tar（Docker 镜像）",8,o)]),a[0]||(a[0]=s("td",null,"61.90 MiB",-1)),a[1]||(a[1]=s("td",null,[s("code",null,"linux/amd64"),t("，导入后镜像名为 "),s("code",null,"h1-web:latest")],-1))]),s("tr",null,[s("td",null,[s("a",{href:i(e)("/downloads/faq/console-guide.pdf"),download:""},"下载《H1任务编排控制台使用说明》（PDF）",8,h)]),a[2]||(a[2]=s("td",null,"3.82 MiB",-1)),a[3]||(a[3]=s("td",null,"完整操作说明",-1))])])]),a[7]||(a[7]=d(`<p>镜像适用于 <code>linux/amd64</code>，请确认电脑架构和机器人配套固件；其他架构需使用对应的软件包。</p><blockquote><p>h1-web 是一个用 <strong>Docker 部署的网页控制台</strong>，浏览器即可操作机器人几乎全部功能：建图、定位、导航、遥控、拖拽式<strong>任务编排</strong>，以及人脸 / 语音 / 手势 / 动作 / 执行器 / 传感器 / 诊断 / TF。相比直接用 SDK，它更适合集成、交付、演示和日常操作。</p></blockquote><h2 id="q34" tabindex="-1">Q34. 控制台怎么部署、启动？ <a class="header-anchor" href="#q34" aria-label="Permalink to &quot;Q34. 控制台怎么部署、启动？ {#q34}&quot;">​</a></h2><p>前提：电脑已安装 Docker，已从<a href="#下载文件">下载区</a>保存 <code>h1-web.tar</code>，并能连接机器人的 HTTP Bridge（默认端口 <code>8766</code>）。在下载文件所在目录执行：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> load</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> h1-web.tar</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> h1-web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 5173:80</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> h1-web:latest</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>浏览器打开 <code>http://localhost:5173</code>。Linux 是否需要在 Docker 命令前加 <code>sudo</code> 取决于本机配置；Docker Desktop 环境通常不需要。</p><h2 id="q35" tabindex="-1">Q35. 怎么连接到机器人？ <a class="header-anchor" href="#q35" aria-label="Permalink to &quot;Q35. 怎么连接到机器人？ {#q35}&quot;">​</a></h2><p>首次打开或点顶部「设置」→ 填入机器人 IP → 确认。后端默认使用 <strong>HTTP Bridge 端口 <code>8766</code></strong>；网线直连示例为 <code>10.42.0.2:8766</code>。前端页面的 <code>5173</code> 端口与机器人后端的 <code>8766</code> 用途不同，不要混填。</p><p>顶部状态栏绿色表示已连接，红色表示连接失败。若部署时修改了后端端口，以配套配置为准。</p><h2 id="q36" tabindex="-1">Q36. 收到新版镜像怎么更新？ <a class="header-anchor" href="#q36" aria-label="Permalink to &quot;Q36. 收到新版镜像怎么更新？ {#q36}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> h1-web</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> h1-web</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rmi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> h1-web:latest</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 可选，释放空间</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> load</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> h1-web.tar</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> h1-web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 5173:80</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> h1-web:latest</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>更新后刷新浏览器即可（Linux 是否需要 <code>sudo</code> 取决于本机 Docker 权限）。</p><h2 id="q37" tabindex="-1">Q37. 操作机器人有没有固定顺序？ <a class="header-anchor" href="#q37" aria-label="Permalink to &quot;Q37. 操作机器人有没有固定顺序？ {#q37}&quot;">​</a></h2><p>有：<strong>先建图 → 再定位 → 最后导航</strong>，不可跳步。<strong>导航、沿路径导航、回充等所有导航类功能，必须在定位成功（<code>locating_success</code>）之后才能使用</strong>，未定位时操作会失败。</p><h2 id="q38" tabindex="-1">Q38. 怎么建图？ <a class="header-anchor" href="#q38" aria-label="Permalink to &quot;Q38. 怎么建图？ {#q38}&quot;">​</a></h2><p>前提：当前无已有地图（有旧地图需先重置 SLAM → 删除地图）。把机器人放到起点 →「建图控制」→ <strong>开始建图</strong> → 用方向键遥控走遍需覆盖区域 → <strong>结束建图</strong>（自动保存）。建图中可「中途保存」；建议<strong>慢速行走</strong>并尽量走<strong>闭合回路</strong>以提高精度。</p><h2 id="q39" tabindex="-1">Q39. 怎么定位？ <a class="header-anchor" href="#q39" aria-label="Permalink to &quot;Q39. 怎么定位？ {#q39}&quot;">​</a></h2><p>前提：已有地图。「定位控制」→ 选起始位置（上次位姿 / 指定位姿 / 充电桩）→ <strong>开始定位</strong> → 等状态变 <code>locating_success</code>。失败就把机器人放回充电桩重试。定位 / 导航过程支持<strong>暂停 / 恢复</strong>。</p><h2 id="q40" tabindex="-1">Q40. 怎么导航到目标点？ <a class="header-anchor" href="#q40" aria-label="Permalink to &quot;Q40. 怎么导航到目标点？ {#q40}&quot;">​</a></h2><p>定位成功后，在地图上<strong>单击</strong>选点（或手动填 X / Y / Heading，弧度 -3.14~3.14）→ <strong>发送目标</strong>。目标点必须在地图<strong>白色自由区内；同一时间只能执行一个导航任务</strong>，导航中可点「停止导航」中止。</p><h2 id="q41" tabindex="-1">Q41. &quot;沿路径导航&quot;和普通导航有什么区别？ <a class="header-anchor" href="#q41" aria-label="Permalink to &quot;Q41. &quot;沿路径导航&quot;和普通导航有什么区别？ {#q41}&quot;">​</a></h2><p>普通导航是机器人<strong>自主规划</strong>路线到单个目标；沿路径导航在「任务编排」里拖入<strong>路径导航</strong>节点，双击后在地图上<strong>依次点选多个路径点</strong>，机器人严格按顺序行走（点间走直线，需绕行就多加中间点），适合固定巡检路线。</p><h2 id="q42" tabindex="-1">Q42. 怎么回充？ <a class="header-anchor" href="#q42" aria-label="Permalink to &quot;Q42. 怎么回充？ {#q42}&quot;">​</a></h2><p><strong>回充 = 两步</strong>：先「回充(到桩前)」导航到充电桩预备位，再「上桩对接」执行上桩。右侧面板有手动「回充」按钮；任务编排里需把两个节点<strong>串联</strong>（先到桩前成功 → 再上桩）。</p><h2 id="q43" tabindex="-1">Q43. 怎么删除地图 / 重新建图？ <a class="header-anchor" href="#q43" aria-label="Permalink to &quot;Q43. 怎么删除地图 / 重新建图？ {#q43}&quot;">​</a></h2><p><strong>必须先点「重置 SLAM」</strong>（使其回到 IDLE）→ 再点「删除地图」。删除<strong>不可撤销</strong>，之后需重新建图 + 定位才能导航。</p><h2 id="q44" tabindex="-1">Q44. 任务编排（自动化流水线）怎么用？ <a class="header-anchor" href="#q44" aria-label="Permalink to &quot;Q44. 任务编排（自动化流水线）怎么用？ {#q44}&quot;">​</a></h2><p>切到「任务编排」→ 从左侧<strong>拖拽节点</strong>到画布 → 从节点输出端口<strong>拖线</strong>到下一节点 → 单击节点编辑参数 → <strong>执行流程</strong>。连线颜色代表触发条件：<strong>🟢 绿 = 成功、🔴 红 = 失败、🟡 黄 = 超时</strong>（可用红色端口做失败处理，例如导航失败 → 回充）。新增<strong>循环执行</strong>节点：设 <code>loop_count</code> 次数，把流程末端连回该节点即可按成功 / 失败 / 超时重复执行。</p><h2 id="q45" tabindex="-1">Q45. 遥控快捷按钮在哪？ <a class="header-anchor" href="#q45" aria-label="Permalink to &quot;Q45. 遥控快捷按钮在哪？ {#q45}&quot;">​</a></h2><p>地图视图右侧面板底部有方向键（▲ 前进 / ▼ 后退 / ◀ 左转 / ▶ 右转 / ■ 停止，按住持续移动、松开即停）</p><h2 id="q46" tabindex="-1">Q46. 控制台常见问题速查 <a class="header-anchor" href="#q46" aria-label="Permalink to &quot;Q46. 控制台常见问题速查 {#q46}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>原因</th><th>解决办法</th></tr></thead><tbody><tr><td>页面打开后没有数据</td><td>IP 配错或网络不通</td><td>点「设置」检查 IP，确认能 ping 通机器人</td></tr><tr><td>地图显示&quot;等待地图数据&quot;</td><td>还没建图</td><td>先执行建图</td></tr><tr><td>&quot;开始建图&quot;点不了</td><td>当前已有地图</td><td>先重置 SLAM → 删除地图</td></tr><tr><td>&quot;发送目标&quot;按钮灰色</td><td>有导航任务正在执行</td><td>等待完成或点「停止导航」</td></tr><tr><td>导航发送后无反应</td><td>未定位成功</td><td>先完成定位（<code>locating_success</code>）</td></tr><tr><td>&quot;删除地图&quot;无效</td><td>SLAM 未重置</td><td>先点「重置 SLAM」</td></tr><tr><td>任务编排执行无反应</td><td>无节点或无连线</td><td>确保画布上有节点且已连线</td></tr><tr><td>Docker 启动失败</td><td>5173 端口被占用</td><td>换端口，如 <code>-p 8080:80</code></td></tr><tr><td>face_sdk / 动作 / 传感器无数据</td><td>机器人端对应服务未启动</td><td>检查机器人端相应进程或 ROS 话题</td></tr></tbody></table>`,32))]))}});export{u as __pageData,F as default};
